  "Puoi avviare chat solo con persone interne all'azienda.": "Du kannst nur mit Personen aus der Firma chatten.",
  "Puoi compilarlo ora.": "Du kannst ihn jetzt ausfüllen.",
  "Puoi creare il gruppo ora e aggiungere persone in seguito.": "Du kannst die Gruppe jetzt erstellen und später Personen hinzufügen.",
  "Puoi eliminare solo i messaggi inviati da te.": "Du kannst nur Nachrichten löschen, die du gesendet hast.",
  "Puoi inserire numero, fornitore e righe dalla foto.": "Du kannst Nummer, Lieferant und Zeilen aus dem Foto übernehmen.",
  "Puoi registrare e riascoltare qui. Torna online per trascrivere.": "Du kannst hier aufnehmen und anhören. Geh wieder online, um abzuschreiben.",
