  "Puoi scegliere il punto sulla mappa. Per aggiornare l’indirizzo, apri la scheda.": "Du kannst den Punkt auf der Karte wählen. Um die Adresse zu ändern, öffne die Karte.",
  "Puoi segnalarlo o registrare il rientro.": "Du kannst es melden oder die Rückgabe erfassen.",
  "Quando l'ufficio ti affida un mezzo, lo trovi qui con i suoi documenti. Per un attrezzo con l'etichetta QR, tocca «Scansiona».": "Wenn das Büro dir ein Fahrzeug gibt, findest du es hier mit seinen Dokumenten. Für ein Werkzeug mit QR-Etikett tipp auf «Scannen».",
  "Quando prendi materiale dall’Inventario, la richiesta compare qui con la risposta del magazzino.": "Wenn du Material aus dem Inventar nimmst, erscheint die Anfrage hier mit der Antwort vom Lager.",
