  "Parti dalla task più urgente, poi timbra sul cantiere e manda il rapportino a fine lavoro.": "Fang mit der dringendsten Aufgabe an, stempel dann auf der Baustelle und schick den Tagesbericht nach Feierabend.",
  "Vai al cantiere e timbra collegando la commessa. Nel giornaliero trovi le indicazioni scelte dalla tua azienda: puoi scrivere o parlare.": "Geh zur Baustelle und stempel mit dem Auftrag verknüpft. Im Tagesbericht findest du die Vorgaben deiner Firma: du kannst schreiben oder sprechen.",
