  "Sono ore aggiuntive: se incluse nelle ore rilevate, sottraile dalle ordinarie qui sopra.": "Das sind zusätzliche Stunden: wenn sie schon in den erfassten Stunden stecken, zieh sie oben von den normalen Stunden ab.",
