  "Proposta inserita. Controlla il rapportino prima di inviarlo.": "Vorschlag eingetragen. Prüf den Tagesbericht, bevor du ihn schickst.",
  "Il giornaliero lo compila il responsabile": "Den Tagesbericht füllt der Verantwortliche aus",
  "Registra entrata e uscita. Puoi aggiungere foto e segnalazioni dalla scheda del cantiere.": "Stempel Beginn und Ende. Fotos und Meldungen kannst du in der Baustellenansicht hinzufügen.",
