  "Avanzamento del modulo": "Fortschritt im Formular",
  "Documento da mostrare al cliente prima della firma. Non è il normale riepilogo di fine giornata.": "Dokument, das du dem Kunden vor der Unterschrift zeigst. Nicht die normale Tageszusammenfassung.",
  "Verifico cantiere e rapporti già inviati…": "Ich prüfe die Baustelle und die schon gesendeten Berichte…",
  "Non riesco a svuotare la bozza sul telefono.": "Ich kann den Entwurf auf dem Handy nicht leeren.",
  "Non riesco a verificare i rapporti o il tuo ruolo. I dati inseriti restano qui; l’invio è sospeso per evitare doppioni.": "Ich kann die Berichte oder deine Rolle nicht prüfen. Deine Eingaben bleiben hier; das Senden ist pausiert, damit nichts doppelt ankommt.",
  "Riprova la verifica": "Prüfung nochmal versuchen",
  "La conferma del cliente è gestita dal capocantiere. Per raccontare la tua giornata torna al rapportino giornaliero.": "Die Bestätigung des Kunden macht der Bauleiter. Um deinen Tag zu beschreiben, geh zurück zum Tagesbericht.",
  "In questa azienda il giornaliero lo invia il responsabile. Tu registra entrata e uscita; puoi aggiungere foto e segnalare problemi dal cantiere.": "In dieser Firma schickt der Verantwortliche den Tagesbericht. Du stempelst Beginn und Ende; du kannst Fotos hinzufügen und Probleme von der Baustelle melden.",
  "I dati compilati restano visibili, ma non vengono spostati a oggi.": "Die ausgefüllten Daten bleiben sichtbar, werden aber nicht auf heute verschoben.",
  "Motivo: {motivo}": "Grund: {motivo}",
  "Per separare i due documenti nello stesso giorno occorre aggiornare il database: non sostituiamo quello già inviato.": "Um die zwei Dokumente am selben Tag zu trennen, muss die Datenbank aktualisiert werden: wir ersetzen das schon gesendete nicht.",
  "{data} — non inviabile": "{data} — kann nicht gesendet werden",
  "Correzione richiesta dall’ufficio: puoi rimandarla anche dopo la scadenza originale.": "Korrektur vom Büro angefordert: du kannst sie auch nach der ursprünglichen Frist schicken.",
  "Da inviare entro oggi alle 23:59.": "Bis heute um 23:59 senden.",
