  "Prima della firma prepara il verbale con verifiche, esito ed eventuali riserve. La richiesta collegata al solo ordine non contiene un documento da firmare.": "Bereite vor der Unterschrift das Protokoll mit Prüfungen, Ergebnis und eventuellen Vorbehalten vor. Die Anfrage, die nur mit dem Auftrag verknüpft ist, enthält kein Dokument zum Unterschreiben.",
