  "Chi ha lavorato oggi?": "Wer hat heute gearbeitet?",
  "Chi ha lavorato in questa giornata?": "Wer hat an diesem Tag gearbeitet?",
  "Le ore sono quelle timbrate in cantiere: controllale e correggile se serve. Chi non ha timbrato lo aggiungi tu, con le sue ore.": "Die Stunden sind die auf der Baustelle gestempelten: prüf sie und korrigier sie, wenn nötig. Wer nicht gestempelt hat, fügst du mit seinen Stunden hinzu.",
  "Tocca chi era in cantiere e scrivi le sue ore. Chi ha già mandato il suo rapportino non va segnato di nuovo.": "Tipp an, wer auf der Baustelle war, und schreib seine Stunden. Wer seinen Tagesbericht schon geschickt hat, wird nicht nochmal eingetragen.",
  "Tocca chi della tua squadra era in cantiere e scrivi le sue ore. Chi ha già mandato il suo rapportino non va segnato di nuovo.": "Tipp an, wer aus deinem Team auf der Baustelle war, und schreib seine Stunden. Wer seinen Tagesbericht schon geschickt hat, wird nicht nochmal eingetragen.",
