  "Ruolo Campo non ancora verificato. Puoi indicare le fasi lavorate; la modifica delle percentuali resta disabilitata.": "Rolle auf der Baustelle noch nicht geprüft. Du kannst die bearbeiteten Phasen angeben; die Prozente kannst du nicht ändern.",
  "Tocca le fasi e indica l'avanzamento raggiunto (facoltativo)": "Tipp die Phasen an und gib den erreichten Fortschritt an (optional)",
  "Tocca le fasi su cui hai lavorato: servono ad attribuire le tue ore. L'avanzamento lo dichiara il capocantiere.": "Tipp die Phasen an, an denen du gearbeitet hast: damit werden deine Stunden zugeordnet. Den Fortschritt meldet der Bauleiter.",
