  "Per verificare l’ordine servono entrambe le misure finite e il riferimento della verifica.": "Zum Prüfen der Bestellung braucht es beide Fertigmaße und den Bezug der Prüfung.",
  "Misure d’ordine non verificate: nessun ordine può essere dedotto dal disegno.": "Bestellmaße nicht geprüft: aus der Zeichnung kann keine Bestellung abgeleitet werden.",
  "Il profilo della zanzariera occuperebbe tutto il vano: verifica valore e unità dello spessore, senza ridimensionamenti automatici.": "Das Profil des Insektenschutzes würde die ganze Öffnung belegen: prüf Wert und Einheit der Stärke, ohne automatische Anpassung.",
  "Direzione e comando della zanzariera discordanti: verifica il modello prima di confermare il disegno.": "Richtung und Bedienung des Insektenschutzes passen nicht zusammen: prüf das Modell, bevor du die Zeichnung bestätigst.",
  "Guida carrarmato: verifica la compatibilità con direzione e guida inferiore; nessuna compatibilità viene certificata dal disegno.": "Raupenführung: prüf die Passung mit Richtung und unterer Führung; die Zeichnung bestätigt keine Passung.",
  "Aletta Z parziale o lati da confermare: lo schema frontale non rappresenta il dettaglio di questa posa.": "Z-Flügel teilweise oder Seiten zu bestätigen: das Frontschema zeigt das Detail dieses Einbaus nicht.",
  "Larghezza e altezza devono essere misure positive.": "Breite und Höhe müssen positive Maße sein.",
  "Controlla guide a sporgere e monoblocco: quote in mm tra 0 e 100.000.": "Prüf Ausstellschienen und Monoblock: Maße in mm zwischen 0 und 100.000.",
  "Controlla spessori e ingombri: usa numeri tra 0 e 100.000 mm.": "Prüf Stärken und Platzbedarf: verwende Zahlen zwischen 0 und 100.000 mm.",
  "Controlla le misure di scorrimento e ripiegamento: usa quote positive in mm, al massimo 100.000.": "Prüf die Schiebe- und Faltmaße: verwende positive Maße in mm, höchstens 100.000.",
  "Controlla le misure tecniche dell’abaco: le quote inserite devono essere maggiori di zero.": "Prüf die technischen Maße der Übersicht: die eingegebenen Maße müssen größer als null sein.",
  "Controlla le misure tecniche: usa numeri tra 0 e 100.000 mm.": "Prüf die technischen Maße: verwende Zahlen zwischen 0 und 100.000 mm.",
  "Il numero di pannelli del soffietto deve essere intero, da 2 a 20.": "Die Anzahl der Paneele der Harmonikatür muss eine ganze Zahl von 2 bis 20 sein.",
