  "Rete e profili rappresentano la tipologia rilevata; spessori non misurati restano illustrativi, non sono misure d’ordine.": "Gewebe und Profile zeigen den aufgemessenen Typ; nicht gemessene Stärken sind nur zur Erklärung, sie sind keine Bestellmaße.",
