  "Cielino e diametro quotati solo se rilevati. Posizione di rullo e pannelli schematica; profili esecutivi secondo il produttore.": "Kastenunterseite und Durchmesser nur bemaßt, wenn gemessen. Lage von Welle und Paneelen schematisch; Ausführungsprofile laut Hersteller.",
