  "Ingombro del telo, stecche illustrative: cassonetto, guide e rullo non vengono aggiunti alle misure.": "Platzbedarf des Panzers, Lamellen nur zur Erklärung: Kasten, Schienen und Welle werden nicht zu den Maßen addiert.",
  "Tratteggio delle stecche campionato per leggibilità; il passo registrato non viene modificato.": "Schraffur der Lamellen zur besseren Lesbarkeit vereinfacht; die gespeicherte Teilung wird nicht geändert.",
